import React, { useState, useMemo } from 'react';
import { 
  Search, Filter, CheckCheck, Clock, Pin, 
  ChevronRight, Star, UserPlus
} from 'lucide-react';

const MessagesList = ({ onSelectMessage }) => {
  const [messages, setMessages] = useState([
    { 
      id: 1, 
      sender: 'John Doe', 
      message: 'Bonjour, j\'ai une question concernant ma commande...', 
      time: '10:30', 
      date: 'Aujourd\'hui',
      unread: true,
      online: true,
      pinned: true,
      verified: true,
      avatarColor: 'from-blue-500 to-cyan-400',
      status: 'Client VIP'
    },
    { 
      id: 2, 
      sender: 'Sarah Smith', 
      message: 'Merci pour votre aide rapide!', 
      time: '14:20', 
      date: 'Aujourd\'hui',
      unread: false,
      online: false,
      pinned: false,
      verified: true,
      avatarColor: 'from-purple-500 to-pink-400',
      status: 'Nouveau client'
    },
    { 
      id: 3, 
      sender: 'Mike Johnson', 
      message: 'Est-ce que le produit sera disponible bientôt?', 
      time: '09:15', 
      date: 'Hier',
      unread: true,
      online: true,
      pinned: true,
      verified: false,
      avatarColor: 'from-amber-500 to-orange-400',
      status: 'Support'
    },
    { 
      id: 4, 
      sender: 'Emma Wilson', 
      message: 'Je confirme la réunion de demain', 
      time: 'Hier',
      date: 'Hier',
      unread: false,
      online: true,
      pinned: false,
      verified: true,
      avatarColor: 'from-emerald-500 to-teal-400',
      status: 'Partenaire'
    },
    { 
      id: 5, 
      sender: 'David Brown', 
      message: 'Document envoyé avec succès', 
      time: '2 jours',
      date: '20 Nov',
      unread: false,
      online: false,
      pinned: false,
      verified: false,
      avatarColor: 'from-red-500 to-rose-400',
      status: 'Client'
    }
  ]);

  const [search, setSearch] = useState('');
  const [filter, setFilter] = useState('all'); // all, unread, pinned
  const [selectedId, setSelectedId] = useState(null);

  // Filtrage et recherche
  const filteredMessages = useMemo(() => {
    let filtered = messages;

    // Filtre par type
    if (filter === 'unread') {
      filtered = filtered.filter(msg => msg.unread);
    } else if (filter === 'pinned') {
      filtered = filtered.filter(msg => msg.pinned);
    }

    // Recherche
    if (search) {
      filtered = filtered.filter(msg =>
        msg.sender.toLowerCase().includes(search.toLowerCase()) ||
        msg.message.toLowerCase().includes(search.toLowerCase()) ||
        msg.status.toLowerCase().includes(search.toLowerCase())
      );
    }

    return filtered;
  }, [messages, search, filter]);

  // Group messages by date
  const groupedMessages = useMemo(() => {
    const groups = {};
    filteredMessages.forEach(msg => {
      if (!groups[msg.date]) {
        groups[msg.date] = [];
      }
      groups[msg.date].push(msg);
    });
    return groups;
  }, [filteredMessages]);

  const handleMessageClick = (message) => {
    setSelectedId(message.id);

    // Marquer comme lu
    if (message.unread) {
      setMessages(prev => prev.map(msg => 
        msg.id === message.id ? { ...msg, unread: false } : msg
      ));
    }

    onSelectMessage(message);
  };

  return (
    <div className="bg-gradient-to-br from-white to-white/80 dark:from-neutral-900 dark:to-neutral-900/80 backdrop-blur-xl rounded-3xl shadow-xl border border-white/40 dark:border-neutral-800/60 h-full overflow-hidden">
      {/* Header */}
      <div className="p-5 border-b border-neutral-200/60 dark:border-neutral-800/60">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-lg font-bold text-neutral-900 dark:text-white">
            Conversations
            <span className="ml-2 px-2 py-1 text-xs bg-primary-500/10 text-primary-600 dark:text-primary-400 rounded-full">
              {messages.filter(m => m.unread).length}
            </span>
          </h2>
          <div className="flex items-center space-x-2">
            <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
              <UserPlus className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
            <button className="p-2 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl transition-colors">
              <Filter className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
            </button>
          </div>
        </div>

        {/* Barre de recherche */}
        <div className="relative group">
          <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
            <Search className="h-4 w-4 text-neutral-400 group-focus-within:text-primary-500 transition-colors" />
          </div>
          <input
            type="search"
            placeholder="Rechercher des conversations..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-11 pr-4 py-3 w-full rounded-2xl border-2 border-neutral-200/60 dark:border-neutral-800/60 bg-white/50 dark:bg-neutral-800/30 text-neutral-900 dark:text-white placeholder-neutral-500 focus:outline-none focus:border-primary-500 focus:ring-4 focus:ring-primary-500/20 transition-all duration-300"
          />
        </div>

        {/* Filtres */}
        <div className="flex space-x-2 mt-4">
          {[
            { id: 'all', label: 'Tous', count: messages.length },
            { id: 'unread', label: 'Non lus', count: messages.filter(m => m.unread).length },
            { id: 'pinned', label: 'Épinglés', count: messages.filter(m => m.pinned).length }
          ].map((filterItem) => (
            <button
              key={filterItem.id}
              onClick={() => setFilter(filterItem.id)}
              className={`px-3 py-1.5 text-sm rounded-xl transition-all duration-300 ${
                filter === filterItem.id
                  ? 'bg-primary-500 text-white shadow-lg shadow-primary-500/25'
                  : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-700 dark:text-neutral-300 hover:bg-neutral-200 dark:hover:bg-neutral-700'
              }`}
            >
              {filterItem.label}
              <span className="ml-1.5 opacity-75">{filterItem.count}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Liste des messages */}
      <div className="overflow-y-auto h-[500px] scrollbar-thin scrollbar-thumb-neutral-300 dark:scrollbar-thumb-neutral-700 scrollbar-track-transparent">
        {Object.entries(groupedMessages).map(([date, msgs]) => (
          <div key={date} className="px-5 pt-5">
            <div className="flex items-center justify-between mb-3">
              <span className="text-xs font-medium text-neutral-500 dark:text-neutral-500 uppercase tracking-wider">
                {date}
              </span>
              <span className="text-xs text-neutral-400 dark:text-neutral-600">
                {msgs.length} conversation{msgs.length > 1 ? 's' : ''}
              </span>
            </div>

            {msgs.map((msg) => (
              <div
                key={msg.id}
                onClick={() => handleMessageClick(msg)}
                className={`
                  relative p-4 rounded-2xl mb-2 cursor-pointer transition-all duration-300
                  ${selectedId === msg.id
                    ? 'bg-gradient-to-r from-primary-50 to-primary-100/50 dark:from-primary-900/30 dark:to-primary-800/20 border-l-4 border-primary-500 shadow-lg'
                    : 'hover:bg-neutral-50/80 dark:hover:bg-neutral-800/30 hover:shadow-md'
                  }
                  ${msg.unread ? 'bg-blue-50/50 dark:bg-blue-900/10' : ''}
                  ${msg.pinned ? 'border-r-4 border-amber-500/30' : ''}
                `}
              >
                {/* Pin indicator */}
                {msg.pinned && (
                  <div className="absolute top-4 right-4">
                    <Pin className="h-4 w-4 text-amber-500" />
                  </div>
                )}

                <div className="flex items-center space-x-3">
                  {/* Avatar */}
                  <div className="relative">
                    <div className={`h-12 w-12 rounded-2xl bg-gradient-to-r ${msg.avatarColor} flex items-center justify-center shadow-lg`}>
                      <span className="text-white font-bold text-lg">
                        {msg.sender.charAt(0)}
                      </span>
                    </div>
                    {msg.online && (
                      <div className="absolute -bottom-1 -right-1 h-4 w-4 bg-green-500 rounded-full border-2 border-white dark:border-neutral-900"></div>
                    )}
                  </div>

                  {/* Content */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <div className="flex items-center space-x-2">
                        <h4 className={`font-semibold truncate ${
                          msg.unread ? 'text-neutral-900 dark:text-white' : 'text-neutral-800 dark:text-neutral-200'
                        }`}>
                          {msg.sender}
                        </h4>
                        {msg.verified && (
                          <span className="h-4 w-4 bg-blue-500 rounded-full flex items-center justify-center">
                            <CheckCheck className="h-3 w-3 text-white" />
                          </span>
                        )}
                        <span className={`text-xs px-2 py-0.5 rounded-full ${
                          msg.status === 'Client VIP' ? 'bg-amber-500/10 text-amber-600 dark:text-amber-400' :
                          msg.status === 'Nouveau client' ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400' :
                          msg.status === 'Support' ? 'bg-blue-500/10 text-blue-600 dark:text-blue-400' :
                          'bg-neutral-500/10 text-neutral-600 dark:text-neutral-400'
                        }`}>
                          {msg.status}
                        </span>
                      </div>
                      <div className="flex items-center space-x-2">
                        <span className={`text-xs ${
                          msg.unread ? 'font-semibold text-primary-600 dark:text-primary-400' : 'text-neutral-500 dark:text-neutral-500'
                        }`}>
                          {msg.time}
                        </span>
                        <ChevronRight className={`h-4 w-4 transition-transform duration-300 ${
                          selectedId === msg.id ? 'rotate-90 text-primary-500' : 'text-neutral-400'
                        }`} />
                      </div>
                    </div>

                    <p className={`text-sm truncate ${
                      msg.unread ? 'text-neutral-700 dark:text-neutral-300 font-medium' : 'text-neutral-600 dark:text-neutral-400'
                    }`}>
                      {msg.message}
                    </p>

                    {/* Message status */}
                    <div className="flex items-center justify-between mt-2">
                      <div className="flex items-center space-x-3">
                        {msg.unread ? (
                          <span className="h-2 w-2 bg-primary-500 rounded-full animate-pulse"></span>
                        ) : (
                          <CheckCheck className="h-4 w-4 text-neutral-400" />
                        )}
                        <span className="text-xs text-neutral-500 dark:text-neutral-500">
                          {msg.unread ? 'Nouveau message' : 'Vu'}
                        </span>
                      </div>
                      {msg.unread && (
                        <span className="px-2 py-1 text-xs font-medium bg-primary-500 text-white rounded-full animate-bounce">
                          Nouveau
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>
    </div>
  );
};

export default MessagesList;
